input.command:
cd /workspace/gold && perl -e '
open(F,"<:raw","expected.txt") or die;
local $/; my $d=<F>; close F;
print "total bytes: ", length($d), "\n";
print "ends with newline: ", ($d =~ /\n$/ ? "YES":"NO"), "\n";
my @L = split(/\n/, $d, -1);
print "split count (incl trailing empty): ", scalar(@L), "\n";
pop @L if $L[-1] eq "";
for my $i (0..$#L) {
  my $l = $L[$i];
  printf("%2d| bytes=%3d | %s\n", $i+1, length($l), join("", map { my $c=$_; ($c=~/[\x20-\x7e]/) ? $c : sprintf("<%02X>", ord($c)) } split //, $l));
}
'
